function freshState(){return {bank:[...structuredClone(SEED),...structuredClone(REQUIRED_PREPS),...structuredClone(EXTRA_SEED)],index:{verb:0,noun:0,connector:0,preposition:0,satzbau:0,bausteine:0,grammar:0},drafts:{},lastChecks:{},history:[],translationReveal:{},reading:{notes:'',pdfName:'',pdfId:''},writing:{topic:0,mode:'practice',customPrompt:'',drafts:{}},listening:{index:0,answers:{}},speaking:{index:0,notes:{}},createdAt:new Date().toISOString()};}
function loadState(){try{
 const raw=localStorage.getItem(STORAGE_KEY); if(!raw)return freshState();
 const d=JSON.parse(raw);if(!Array.isArray(d.bank)||!Array.isArray(d.history))return freshState();
 const restored={...freshState(),...d};
 // Migración 0.3: conserva tus respuestas, historial y fichas importadas.
 // Solo actualiza la información gramatical de los registros iniciales corregidos.
 for(const id of ['v_beschweren','v_bewerben','v_freuen']){
  const existing=restored.bank.find(item=>item.id===id);
  const updated=SEED.find(item=>item.id===id);
  if(existing&&updated){existing.prepositions=structuredClone(updated.prepositions);existing.example=updated.example;}
 }
 for(const id of ['p_beschweren_bei','p_bewerben_bei','p_freuen_ueber']){
  if(!restored.bank.some(item=>item.id===id))restored.bank.push(structuredClone(SEED.find(item=>item.id===id)));
 }
  // Migración 0.5: suma los verbos del libro sin borrar respuestas, estadísticas ni vocabulario anterior.
  const ids=new Set(restored.bank.map(x=>x.id));
  for(const entry of REQUIRED_PREPS){if(!ids.has(entry.id)){restored.bank.push(structuredClone(entry));ids.add(entry.id);}}
  // Migración 0.6: registra ejercicios nuevos; no modifica respuestas antiguas.
  restored.index={...freshState().index,...(restored.index||{})};
  for(const entry of EXTRA_SEED){if(!restored.bank.some(x=>x.id===entry.id))restored.bank.push(structuredClone(entry));}
  restored.translationReveal??={};restored.reading??={notes:'',pdfName:'',pdfId:''};
  restored.writing??={topic:0,mode:'practice',customPrompt:'',drafts:{}};restored.writing.drafts??={};
  restored.listening??={index:0,answers:{}};restored.listening.answers??={};
  restored.speaking??={index:0,notes:{}};restored.speaking.notes??={};
  return restored;
 }catch(e){return freshState();}}
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch(e){showToast('No se puede guardar. Libera almacenamiento y exporta una copia.');}}
function html(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function normalize(s){return String(s??'').trim().toLocaleLowerCase('de-DE').replace(/[.!,;:]+$/g,'').replace(/\s+/g,' ').replace(/’/g,"'");}
function itemBank(type){
 if(type==='errors'){
   const failed=state.history.filter(h=>h.total>h.correct&&state.bank.some(i=>i.id===h.id));
   const ids=[...new Set(failed.reverse().map(h=>h.id))];
   return ids.map(id=>state.bank.find(i=>i.id===id)).filter(Boolean);
 }
 if(['reading','writing','listening','speaking'].includes(type))return [];
 const list=state.bank.filter(i=>i.type===type);
 return type==='preposition'?[...list.filter(i=>i.id.startsWith('p_sicher_')),...list.filter(i=>!i.id.startsWith('p_sicher_'))]:list;
}
function currentItem(type){const bank=itemBank(type); if(!bank.length)return null;const index=Math.max(0,Math.min((state.index[type]||0),bank.length-1));state.index[type]=index;return bank[index];}
function qid(item){return item.type+'::'+item.id;}
function draftFor(item){return state.drafts[qid(item)]||{};}
function checkedFor(item){return state.lastChecks[qid(item)]||null;}
function moduleCount(){return ['verb','noun','connector','preposition','satzbau','bausteine','grammar'].reduce((a,k)=>a+itemBank(k).length,0);}
function accuracy(){const total=state.history.reduce((n,r)=>n+(r.total||0),0);const right=state.history.reduce((n,r)=>n+(r.correct||0),0);return total?Math.round(right/total*100):0;}
function feedbackHTML(key,expected,check){if(!check)return '';const match=check.fields?.[key];if(match)return '<div class="feedback good">✓ Correcto</div>';return `<div class="feedback bad">✕ Revisa esta respuesta.<span class="correct-text">Respuesta: ${html(expected)}</span></div>`;}
function optionsField(key, label, options, answer, item, check){let val=draftFor(item)[key]??'';let cls=check?(check.fields?.[key]?' correct':' error'):'';
 return `<div class="field"><label for="f_${html(key)}">${html(label)}</label><select id="f_${html(key)}" class="select-answer${cls}" data-key="${html(key)}" ${check?'disabled':''}><option value="">Selecciona...</option>${options.map(x=>`<option value="${html(x)}" ${x===val?'selected':''}>${html(x)}</option>`).join('')}</select>${feedbackHTML(key,answer,check)}</div>`;}
function textField(key,label,answer,item,check,placeholder='Escribe tu respuesta'){let val=draftFor(item)[key]??'';let cls=check?(check.fields?.[key]?' correct':' error'):'';
 return `<div class="field"><label for="f_${html(key)}">${html(label)}</label><input id="f_${html(key)}" class="answer${cls}" type="text" autocapitalize="off" autocomplete="off" autocorrect="off" enterkeyhint="next" spellcheck="false" data-key="${html(key)}" value="${html(val)}" placeholder="${html(placeholder)}" ${check?'readonly':''}>${feedbackHTML(key,answer,check)}</div>`;}
function nounForm(item,caseKey,group){const g=item.gender;const sg=item.singular;const base=(caseKey==='Gen')?item.genitive:sg;const pl=(caseKey==='Dat')?item.dativePlural:item.plural;
 const art={
 def:{m:{Nom:'der',Akk:'den',Dat:'dem',Gen:'des'},f:{Nom:'die',Akk:'die',Dat:'der',Gen:'der'},n:{Nom:'das',Akk:'das',Dat:'dem',Gen:'des'}},
 indef:{m:{Nom:'ein',Akk:'einen',Dat:'einem',Gen:'eines'},f:{Nom:'eine',Akk:'eine',Dat:'einer',Gen:'einer'},n:{Nom:'ein',Akk:'ein',Dat:'einem',Gen:'eines'}}
 };
 const endings={
 def:{m:{Nom:'e',Akk:'en',Dat:'en',Gen:'en'},f:{Nom:'e',Akk:'e',Dat:'en',Gen:'en'},n:{Nom:'e',Akk:'e',Dat:'en',Gen:'en'}},
 indef:{m:{Nom:'er',Akk:'en',Dat:'en',Gen:'en'},f:{Nom:'e',Akk:'e',Dat:'en',Gen:'en'},n:{Nom:'es',Akk:'es',Dat:'en',Gen:'en'}},
 bare:{m:{Nom:'er',Akk:'en',Dat:'em',Gen:'en'},f:{Nom:'e',Akk:'e',Dat:'er',Gen:'er'},n:{Nom:'es',Akk:'es',Dat:'em',Gen:'en'}},
 plDef:{Nom:'en',Akk:'en',Dat:'en',Gen:'en'},plBare:{Nom:'e',Akk:'e',Dat:'en',Gen:'er'}
 };
 let article='',suffix='',noun='';
 if(group==='plDef'){article={Nom:'die',Akk:'die',Dat:'den',Gen:'der'}[caseKey];suffix=endings.plDef[caseKey];noun=pl;}
 else if(group==='plBare'){suffix=endings.plBare[caseKey];noun=pl;}
 else {article=art[group]?.[g]?.[caseKey]||'';suffix=endings[group]?.[g]?.[caseKey]||'';noun=base;}
 return `${article?article+' ':''}${item.adjective+suffix} ${noun}`;
}
function verbPrepFields(item){
 const alternatives=Array.isArray(item.prepositions)&&item.prepositions.length?item.prepositions:[{preposition:item.preposition,case:item.case,usage:''}];
 const choices=[...new Set(['—',...PREPOSITION_CHOICES,...alternatives.map(x=>x.preposition)])];
 const cases=['Ninguno','Nominativ','Akkusativ','Dativ','Genitiv'];
 return alternatives.flatMap((entry,i)=>{
  const suffix=i?String(i+1):'';
  const title=alternatives.length>1?` ${i+1}`:'';
  const detail=entry.usage?` · ${entry.usage}`:'';
  return [
   {key:'prep'+suffix,label:'Preposición'+title+detail,answer:entry.preposition,options:choices},
   {key:'case'+suffix,label:'Caso de la preposición'+title,answer:entry.case,options:cases}
  ];
 });
}
function questionFields(item){if(item.type==='verb')return [
 {key:'inf',label:'Infinitivo en alemán',answer:item.infinitive},
 ...PRONOUNS.map((p,i)=>({key:'p'+i,label:p,answer:item.present[i]})),
 {key:'reflex',label:'¿Es reflexivo?',answer:item.reflexive,options:['Sí','No']},
 {key:'aux',label:'Auxiliar Perfekt',answer:item.auxiliary,options:['haben','sein']},
 {key:'part',label:'Partizip II',answer:item.participle},
 ...verbPrepFields(item)
 ];
 if(item.type==='noun')return [
 ...['def','indef','bare','plDef','plBare'].flatMap(group=>CASES.map(([c,label])=>({key:group+c,label:label,answer:nounForm(item,c,group),group})))
 ];
 if(item.type==='connector')return [{key:'connector',label:'Conector que falta',answer:item.answer,alternatives:item.alternatives||[]}];
 if(['satzbau','bausteine','grammar'].includes(item.type)){return [{key:'answer',label:item.type==='satzbau'?'Oración completa en alemán':'Palabra que falta',answer:item.answer,alternatives:item.alternatives||[]}];}
 if(item.type==='preposition'){
  if(Array.isArray(item.prepositions)&&item.prepositions.length){
   return item.prepositions.flatMap((entry,i)=>{
    const suffix=i?String(i+1):'';
    const text='Construcción '+(i+1)+(entry.usage?' · '+entry.usage:'');
    return [
     {key:'prep'+suffix,label:'Preposición · '+text,answer:entry.preposition,options:[...new Set([...PREPOSITION_CHOICES,...item.prepositions.map(x=>x.preposition)])]},
     {key:'case'+suffix,label:'Caso · construcción '+(i+1),answer:entry.case,options:['Nominativ','Akkusativ','Dativ','Genitiv']}
    ];
   });
  }
  return [
   {key:'prep',label:'Preposición que falta',answer:item.preposition},
   {key:'case',label:'Caso gramatical',answer:item.case,options:['Nominativ','Akkusativ','Dativ','Genitiv']}
  ];
 }
 return [];
}
