async function mediaDB(){return new Promise((resolve,reject)=>{if(!('indexedDB' in window))return reject(Error('Almacenamiento de archivos no disponible.'));
 const req=indexedDB.open('DeutschTrainerMedia',1);req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains('files'))req.result.createObjectStore('files');};req.onerror=()=>reject(req.error);req.onsuccess=()=>resolve(req.result);});}
async function mediaPut(key,value){const db=await mediaDB();return new Promise((resolve,reject)=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').put(value,key);tx.oncomplete=()=>{db.close();resolve();};tx.onerror=()=>{db.close();reject(tx.error);};});}
async function mediaGet(key){const db=await mediaDB();return new Promise((resolve,reject)=>{const tx=db.transaction('files','readonly');const r=tx.objectStore('files').get(key);r.onsuccess=()=>{db.close();resolve(r.result)};r.onerror=()=>{db.close();reject(r.error)};});}
async function mediaRemove(key){const db=await mediaDB();return new Promise((resolve,reject)=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').delete(key);tx.oncomplete=()=>{db.close();resolve();};tx.onerror=()=>{db.close();reject(tx.error)};});}
async function saveReadingPDF(file){if(!file)return;try{if(file.size>15_000_000)throw Error('El PDF supera 15 MB.');if(!(/\.pdf$/i.test(file.name)||file.type==='application/pdf'))throw Error('Selecciona un PDF.');await mediaPut('reading_pdf',file);state.reading.pdfName=file.name;state.reading.pdfId='reading_pdf';save();renderReading();showToast('PDF guardado en tu dispositivo.');}catch(e){showToast('No se pudo guardar PDF: '+e.message)}}
async function openReadingPDF(){try{const file=await mediaGet('reading_pdf');if(!file){showToast('No hay PDF guardado.');return;}const url=URL.createObjectURL(file);const holder=document.getElementById('pdfHolder');if(holder)holder.innerHTML=`<div class="pdf-container"><a href="${url}" target="_blank" rel="noopener">Abrir PDF en una pestaña</a><iframe title="PDF de lectura" src="${url}"></iframe></div>`;}catch(e){showToast('No se pudo abrir el PDF.')}}
async function clearReadingPDF(){if(!confirm('¿Eliminar el PDF guardado? Tu resumen se conservará.'))return;await mediaRemove('reading_pdf');state.reading.pdfId='';state.reading.pdfName='';save();renderReading();}
async function saveLocalAudio(file){if(!file)return;try{if(file.size>15_000_000)throw Error('El audio supera 15 MB.');if(!file.type.startsWith('audio/'))throw Error('Selecciona audio.');await mediaPut('listening_audio',file);showToast('Audio guardado en el dispositivo.');}catch(e){showToast('No se pudo guardar audio: '+e.message)}}
async function openLocalAudio(){const file=await mediaGet('listening_audio');if(!file)return showToast('No tienes audio guardado.');const url=URL.createObjectURL(file),h=document.getElementById('localAudioHolder');if(h)h.innerHTML=`<audio controls src="${url}" aria-label="Audio importado"></audio>`;}
async function clearLocalAudio(){await mediaRemove('listening_audio');const h=document.getElementById('localAudioHolder');if(h)h.innerHTML='';showToast('Audio eliminado.');}
function playGerman(){if(!('speechSynthesis' in window)){showToast('La voz alemana no está disponible en este navegador.');return;}
 const h=HEARING[state.listening.index], voices=speechSynthesis.getVoices(),voice=voices.find(v=>v.lang.toLowerCase().startsWith('de'));const utter=new SpeechSynthesisUtterance(h.text);utter.lang='de-DE';utter.rate=.85;if(voice)utter.voice=voice;speechSynthesis.cancel();speechSynthesis.speak(utter);showToast('Si no escuchas nada, instala una voz alemana en el dispositivo.');}
function toggleTranscript(){const el=document.getElementById('listenTranscript');if(el)el.hidden=!el.hidden;}
function checkListening(){const answer=(state.listening.answers[state.listening.index]||'').toLocaleLowerCase('de-DE'),h=HEARING[state.listening.index];const correct=h.keywords.every(k=>answer.includes(k));const target=document.getElementById('listenFeedback');if(target)target.innerHTML=`<div class="feedback ${correct?'good':'bad'}">${correct?'✓ Respuesta clave identificada':'La respuesta no contiene todos los datos esperados.'}<span class="correct-text">Respuesta modelo: ${html(h.answer)}</span></div>`;
 state.history.push({at:new Date().toISOString(),type:'listening',id:'hear_'+state.listening.index,total:1,correct:correct?1:0});save();}
let activeRecorder=null,recordChunks=[],recordStream=null;
async function startSpeechRecording(){if(activeRecorder&&activeRecorder.state==='recording')return;try{if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw Error('El micrófono no es compatible con este navegador.');recordStream=await navigator.mediaDevices.getUserMedia({audio:true});recordChunks=[];activeRecorder=new MediaRecorder(recordStream);activeRecorder.ondataavailable=e=>{if(e.data.size)recordChunks.push(e.data)};activeRecorder.onstop=async()=>{const recording=new Blob(recordChunks,{type:activeRecorder.mimeType||'audio/webm'});if(recording.size){try{await mediaPut('speaking_recording_'+state.speaking.index,recording);showToast('Grabación guardada localmente.');}catch(e){showToast('No se pudo guardar: '+e.message)}}recordStream?.getTracks().forEach(x=>x.stop());recordStream=null;const node=document.getElementById('recordStatus');if(node)node.textContent='Grabación detenida y guardada.';};activeRecorder.start();document.getElementById('stopRecord').disabled=false;document.getElementById('recordStatus').textContent='● Grabando…';}catch(e){showToast('Grabación no disponible: '+e.message)}}
function stopSpeechRecording(){if(activeRecorder?.state==='recording'){activeRecorder.stop();const node=document.getElementById('stopRecord');if(node)node.disabled=true;}}
async function playSpeechRecording(){const file=await mediaGet('speaking_recording_'+state.speaking.index);if(!file)return showToast('Graba primero una respuesta.');const url=URL.createObjectURL(file),h=document.getElementById('playbackHolder');if(h)h.innerHTML=`<audio controls autoplay src="${url}" aria-label="Mi grabación"></audio>`;}
function promptForAI(kind){if(kind==='reading')return `Eres un profesor de alemán B2. He leído un PDF y he escrito este resumen en alemán. Evaluación: (1) comprensión y fidelidad de las ideas, (2) información omitida, (3) gramática y vocabulario; marca errores en rojo si el formato lo permite, explica cada error en español, ofrece versión corregida y tres ejercicios de refuerzo. NO inventes lo que dice el PDF. Si no hay PDF adjunto, solicita que lo adjunte antes de valorar comprensión.\n\nMi resumen:\n${state.reading.notes||'(sin resumen todavía)'}\n\nVoy a adjuntar el PDF en ChatGPT.`;
 if(kind==='writing-prompt')return 'Crea un enunciado original para una carta de reclamación (Beschwerdebrief) tipo TELC Deutsch B2, completamente en alemán. Incluye contexto realista, anuncio o promesa original, cuatro puntos de contenido que debo tratar y el destinatario. No escribas la carta ni la solución. Nivel B2. Debe diferenciarse de hoteles, cursos y compras típicas.';
 if(kind==='writing'){const t=LETTER_TOPICS[state.writing.topic]||LETTER_TOPICS[0],draft=state.writing.drafts[writingKey()]||'';return `Evalúa mi Beschwerdebrief tipo TELC Deutsch B2. Usa nuestra escala de práctica orientativa de 45 puntos: contenido 0–15; organización/adecuación 0–15; corrección lingüística 0–15. No presentes esta escala como puntuación oficial TELC. Lista TODOS los errores con explicación en español, propón una versión corregida, distingue errores de estilo de errores gramaticales y dame recomendaciones de mejora.\n\nEnunciado del ejercicio: ${state.writing.customPrompt?.trim()||t.scenario}\n\nMi carta:\n${draft||'(sin carta todavía)'}`;}
 if(kind==='speaking'){const t=SPEAK_TOPICS[state.speaking.index],notes=state.speaking.notes[state.speaking.index]||'';return `Corrige en español mi preparación/transcripción de una respuesta oral TELC B2. Analiza gramática, vocabulario, cohesión y recursos para argumentar. No evalúes pronunciación si no adjunto audio. Tema: ${t.title}. Tarea: ${t.task}. Texto: ${notes||'(sin texto todavía)'}`;}
 return '';
}
function prepareAI(kind){const text=promptForAI(kind);const previous=document.getElementById('aiDialog');if(previous)previous.remove();const modal=document.createElement('div');modal.id='aiDialog';modal.className='ai-overlay';modal.innerHTML=`<div class="ai-modal"><h2>${kind==='writing-prompt'?'Generar un nuevo enunciado':'Preparar corrección con IA'}</h2><p>Con conexión: copia esta solicitud, abre ChatGPT y pégala allí. ${kind==='reading'?'Adjunta también el PDF.':''}</p><textarea id="aiPrompt" class="work-textarea" rows="9" readonly>${html(text)}</textarea><div class="toolbar"><button class="btn" data-action="ai-copy">Copiar solicitud</button><a href="https://chatgpt.com/" target="_blank" rel="noopener noreferrer" class="btn secondary">Abrir ChatGPT ↗</a><button class="btn ghost" data-action="ai-close">Cerrar</button></div></div>`;document.body.appendChild(modal);}
function copyAIPrompt(){const field=document.getElementById('aiPrompt');if(!field)return;const value=field.value;const fallback=()=>{field.focus();field.select();const ok=document.execCommand?.('copy');showToast(ok?'Solicitud copiada.':'Selecciona el texto y elige Copiar.');};if(navigator.clipboard?.writeText){navigator.clipboard.writeText(value).then(()=>showToast('Solicitud copiada. Ábrela en ChatGPT.'),fallback);}else fallback();}

/* Delegación de eventos: escribir nunca vuelve a dibujar campos anteriores. */
document.addEventListener('input',ev=>{
 if(ev.target.id==='readingNotes'){state.reading.notes=ev.target.value;save();}
 if(ev.target.id==='writingDraft'){state.writing.drafts[writingKey()]=ev.target.value;save();updateWordCount(ev.target.value);}
 if(ev.target.id==='writingCustom'){state.writing.customPrompt=ev.target.value;save();}
 if(ev.target.id==='speakingNotes'){state.speaking.notes[state.speaking.index]=ev.target.value;save();}
 if(ev.target.id==='listenAnswer'){state.listening.answers[state.listening.index]=ev.target.value;save();}
 if(ev.target.dataset.key&&currentModule){const item=currentItem(currentModule);if(item){const key=qid(item);state.drafts[key]??={};state.drafts[key][ev.target.dataset.key]=ev.target.value;save();}}
 if(ev.target.id==='wordSearch'){wordQuery=ev.target.value;const list=state.bank.filter(i=>`${i.de} ${i.es} ${i.source||''}`.toLocaleLowerCase().includes(wordQuery.toLocaleLowerCase()));document.getElementById('wordResults').innerHTML=list.map(wordHTML).join('')||'<div class="empty">Sin resultados.</div>';}
});
document.addEventListener('change',ev=>{
 if(ev.target.id==='readingPDF')saveReadingPDF(ev.target.files?.[0]);
 if(ev.target.id==='localAudio')saveLocalAudio(ev.target.files?.[0]);
 if(ev.target.id==='writingMode'){state.writing.mode=ev.target.value;save();renderWriting();}
 if(ev.target.id==='writingTopic'){state.writing.topic=Number(ev.target.value)||0;save();renderWriting();}
if(ev.target.dataset.key&&currentModule){const item=currentItem(currentModule);if(item){const key=qid(item);state.drafts[key]??={};state.drafts[key][ev.target.dataset.key]=ev.target.value;save();}}if(ev.target.id==='fileImport')importFile(ev.target.files?.[0]);});
document.addEventListener('submit',ev=>{if(ev.target.id==='addWord'){ev.preventDefault();const fd=new FormData(ev.target);const de=String(fd.get('de')||'').trim();const es=String(fd.get('es')||'').trim();if(!de||!es)return;addRecords([{type:'pending',de,es,source:'Anotada por mí'}]);}});
/* Tab y Mayús+Tab usan el orden NATIVO del navegador, sin interceptar pulsaciones.
   Intro sigue avanzando desde campos de texto sin volver a dibujar la ficha. */
function focusAdjacentField(origin, direction){
 const fields=Array.from(main.querySelectorAll('input[data-key]:not([readonly]):not([disabled]),select[data-key]:not([disabled])'));
 const index=fields.indexOf(origin);
 if(index<0)return false;
 const target=fields[index+direction];
 if(target){target.focus();target.scrollIntoView({block:'nearest'});return true;}
 if(direction===1){const checkBtn=main.querySelector('[data-action="check"]');if(checkBtn){checkBtn.focus();checkBtn.scrollIntoView({block:'nearest'});return true;}}
 return false;
}
document.addEventListener('keydown',ev=>{
 if(!currentModule||!ev.target.matches('input[data-key],select[data-key]')||ev.isComposing)return;
 if(ev.key==='Enter'&&ev.target.matches('input[data-key]')){
  if(focusAdjacentField(ev.target,1))ev.preventDefault();
 }
});
document.addEventListener('click',ev=>{const nav=ev.target.closest('[data-nav]');if(nav){setView(nav.dataset.nav);return;}if(ev.target.closest('#brand')){setView('home');return;}const mod=ev.target.closest('[data-module]');if(mod){setView('practice',mod.dataset.module);return;}const rm=ev.target.closest('[data-remove]');if(rm){const id=rm.dataset.remove;const item=state.bank.find(i=>i.id===id);if(item?.type==='pending'&&confirm(`¿Eliminar ${item.de} de tus palabras pendientes?`)){state.bank=state.bank.filter(i=>i.id!==id);save();renderWords();}return;}const a=ev.target.closest('[data-action]');if(!a)return;switch(a.dataset.action){case 'open-modules':setView('practice');break;case 'words':setView('words');break;case 'check':handleCheck();break;case 'next':nextQuestion();break;case 'retry':retryQuestion();break;case 'ai-copy':copyAIPrompt();break;case 'ai-close':document.getElementById('aiDialog')?.remove();break;case 'export':exportData();break;case 'toggle-translation':{const item=currentItem(currentModule);if(item){const k=qid(item);state.translationReveal[k]=!state.translationReveal[k];save();renderQuestion();}break;}case 'pdf-open':openReadingPDF();break;case 'pdf-clear':clearReadingPDF();break;case 'reading-ai':prepareAI('reading');break;case 'writing-ai':prepareAI('writing');break;case 'writing-new-ai':prepareAI('writing-prompt');break;case 'listen-play':playGerman();break;case 'listen-transcript':toggleTranscript();break;case 'listen-check':checkListening();break;case 'listen-next':state.listening.index=(state.listening.index+1)%HEARING.length;save();renderListening();break;case 'audio-open':openLocalAudio();break;case 'audio-clear':clearLocalAudio();break;case 'speak-start':startSpeechRecording();break;case 'speak-stop':stopSpeechRecording();break;case 'speak-next':state.speaking.index=(state.speaking.index+1)%SPEAK_TOPICS.length;save();renderSpeaking();break;case 'speaking-ai':prepareAI('speaking');break;case 'speak-play':playSpeechRecording();break;}});
window.addEventListener('online',updateStatus);window.addEventListener('offline',updateStatus);
updateStatus();render();
if('serviceWorker' in navigator&&location.protocol==='https:'||('serviceWorker' in navigator&&location.hostname==='localhost')){
 window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(err=>console.info('No se pudo registrar el modo sin conexión:',err)));
}
